from pathlib import Path
import json,struct,hashlib,math
import numpy as np
p=Path(__file__).resolve().parent;reference=json.loads((p/'random-reference.json').read_text());reports=[]
for n,h in [(2,1),(4,2),(8,2)]:
 N=64;m=h+1;blob=(p/f'random-n{n}.bin').read_bytes();assert hashlib.sha256(blob).hexdigest()==reference[str(n)]['sha256'];z=np.frombuffer(blob,dtype='<f4',offset=12).astype(float);k=0;A=z[k:k+N*n*n].reshape(N,n,n);k+=N*n*n;J=z[k:k+N*m*n].reshape(N,m,n);k+=N*m*n;b=z[k:k+N*m].reshape(N,m);k+=N*m;v=z[k:k+N*n].reshape(N,n);out=json.loads((p/f'crow-mixed-random-n{n}.json').read_text());assert out['success'] and out['published'];X=np.array(out['velocity']).reshape(N,n);L=np.array(out['impulse']).reshape(N,m)
 for i in range(N):
  x,l=X[i],L[i];ref=reference[str(n)]['cases'][i];a=A[i]@(x-v[i]);jt=J[i].T@l;momentum=float(np.max(abs(a-jt))/(1+np.max(abs(a))+np.max(abs(jt))));hard=float(np.max(abs(J[i,:h]@x+b[i,:h])));slack=float(J[i,h]@x+b[i,h]+float(np.float32(.02))*l[h]);comp=abs(float(l[h]*slack));dx=float(np.max(abs(x-ref['velocity'])));dl=float(np.max(abs(l-ref['impulse'])));ok=out['paths'][i]==4 and dx<2e-5 and dl<2e-5 and momentum<=1e-5 and hard<=2e-5 and l[h]>=-2e-5 and slack>=-2e-5 and comp<=2e-5;reports.append({'n':n,'case':i,'active':ref['active'],'path':out['paths'][i],'velocity_gap':dx,'impulse_gap':dl,'momentum':momentum,'hard':hard,'normal_impulse':float(l[h]),'slack':slack,'complementarity':comp,'pass':bool(ok)})
summary={'cases':len(reports),'failures':[x for x in reports if not x['pass']],'max_velocity_gap':max(x['velocity_gap'] for x in reports),'max_impulse_gap':max(x['impulse_gap'] for x in reports),'max_momentum':max(x['momentum'] for x in reports),'max_hard':max(x['hard'] for x in reports),'max_complementarity':max(x['complementarity'] for x in reports),'cases_detail':reports};(p/'random-analysis.json').write_text(json.dumps(summary,indent=2)+'\n');print(json.dumps({k:v for k,v in summary.items() if k!='cases_detail'},indent=2))
